"use client";

import { useState } from "react";
import Logo from "@/../public/logo.svg";
import Image from "next/image";
import { useForm } from "react-hook-form";

import { Form } from "@/components/ui/form";
import FormInput from "@/components/ui/form-input";
import PrimaryButton from "@/components/ui/primary-button";
import { useSignIn, useSignUp } from "../hooks/use-auth";

export default function FormAuth() {

  const [resister, setRegister] = useState<boolean>(true);

  const form = useForm({
    defaultValues: {
      name: "",
      lastname: "",
      email: "",
      password: "",
    },
  });

  const signUpMutate = useSignUp();
  const signInMutate = useSignIn();


  const registerSubmit = (data: FormData) => {
    signUpMutate.mutate(data)
  };

  const loginSubmit = (data: FormData) => {
    signInMutate.mutate(data)
  };


  return (
    <div className="w-full h-full py-20 space-y-10 text-neutral-200">

      {/* TOP */}

      <div className="flex flex-col gap-2">

        <Image
          src={Logo}
          alt="aayeshol"
          width={65}
          height={65}
          className="rounded-md"
        />

        <h1 className="text-4xl font-geist-sans font-medium">
          {resister ? "Create an account" : "Welcome back"}
        </h1>

        <p className="w-4/5 text-base font-funnel-display tracking-wide text-neutral-500">
          {resister
            ? "Create your Aayeshol account to start generating trending AI-powered posts automatically."
            : "Sign in to your Aayeshol dashboard and continue automating your social media content."}
        </p>

      </div>

      {/* FORM */}

      <Form {...form}>

        <form
          onSubmit={form.handleSubmit(
            resister ? registerSubmit : loginSubmit
          )}
          className="w-4/5 space-y-6"
        >

          {/* REGISTER FIELDS */}

          {resister && (
            <div className="grid grid-cols-2 gap-4">

              <FormInput
                control={form.control}
                name="name"
                label="Name"
                placeholder="Johan"
              />

              <FormInput
                control={form.control}
                name="lastname"
                label="Last Name"
                placeholder="Doe"
              />

            </div>
          )}

          {/* EMAIL */}

          <FormInput
            control={form.control}
            name="email"
            label="Email"
            placeholder="example@gmail.com"
            type="email"
            autoComplete="email"
          />

          {/* PASSWORD */}

          <FormInput
            control={form.control}
            name="password"
            type="password"
            label="Password"
            placeholder="••••••••"
            autoComplete={
              resister ? "new-password" : "current-password"
            }
          />

          <PrimaryButton>
            {resister ? "Register" : "Login"}
          </PrimaryButton>

        </form>

      </Form>

      {/* BOTTOM SWITCH */}

      <div>

        {resister ? (
          <p>
            Already have an account?
            <span
              onClick={() => setRegister(!resister)}
              className="font-funnel-display underline underline-offset-2 cursor-pointer ml-1"
            >
              Login
            </span>
          </p>
        ) : (
          <p>
            Don&apos;t have an account?
            <span
              onClick={()=> {setRegister(!resister)}}
              className="font-funnel-display underline underline-offset-2 cursor-pointer ml-1"
            >
              Register
            </span>
          </p>
        )}

      </div>

    </div>
  );
}